const BASE_URL = 'http://localhost:8000/books'

export async function listBooks() {
  const res = await fetch(BASE_URL)
  if (!res.ok) throw new Error('Failed to list books')
  return res.json()
}

export async function createBook(book) {
  const res = await fetch(BASE_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(book),
  })
  if (!res.ok) throw new Error('Failed to create book')
  return res.json()
}

export async function updateBookStatus(id, status) {
  const res = await fetch(`${BASE_URL}/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })
  if (!res.ok) throw new Error('Failed to update book status')
  return res.json()
}

import { useEffect, useState } from 'react'
import { listBooks, updateBookStatus } from '../api'

export default function BookList() {
  const [books, setBooks] = useState([])
  const [error, setError] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    listBooks()
      .then((data) => setBooks(data))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false))
  }, [])

  async function handleStatusChange(id, status) {
    try {
      const updated = await updateBookStatus(id, status)
      setBooks((prev) => prev.map((b) => (b.id === id ? updated : b)))
    } catch (err) {
      setError(err.message)
    }
  }

  if (loading) return <p>Caricamento...</p>
  if (error) return <p>Errore: {error}</p>
  if (!books.length) return <p>Nessun libro presente.</p>

  return (
    <ul>
      {books.map((book) => (
        <li key={book.id}>
          <strong>{book.title}</strong> — {book.author}{' '}
          <select
            value={book.status}
            onChange={(e) => handleStatusChange(book.id, e.target.value)}
          >
            <option value="to_read">Da leggere</option>
            <option value="reading">In lettura</option>
            <option value="read">Letto</option>
          </select>
        </li>
      ))}
    </ul>
  )
}

import { useState } from 'react'
import { createBook } from '../api'

export default function BookForm() {
  const [title, setTitle] = useState('')
  const [author, setAuthor] = useState('')
  const [status, setStatus] = useState('to_read')
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  async function handleSubmit(e) {
    e.preventDefault()
    setError(null)
    setSubmitting(true)
    try {
      await createBook({ title, author, status })
      setTitle('')
      setAuthor('')
      setStatus('to_read')
    } catch (err) {
      setError(err.message)
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>
          Titolo:{' '}
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
          />
        </label>
      </div>
      <div>
        <label>
          Autore:{' '}
          <input
            type="text"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            required
          />
        </label>
      </div>
      <div>
        <label>
          Stato:{' '}
          <select value={status} onChange={(e) => setStatus(e.target.value)}>
            <option value="to_read">Da leggere</option>
            <option value="reading">In lettura</option>
            <option value="read">Letto</option>
          </select>
        </label>
      </div>
      <button type="submit" disabled={submitting}>
        {submitting ? 'Salvataggio...' : 'Aggiungi libro'}
      </button>
      {error && <p>Errore: {error}</p>}
    </form>
  )
}
